 @Test void duplicateSuccessAndEventReplayNeverDuplicatePeriodOrAudit()throws Exception{var a=actor();UUID m=membership(a,1);var q=quote(a,m,plan(2,"1"));UUID key=UUID.randomUUID(),id=UUID.fromString((String)q.get("id"));var r=settle(q,"SUCCESS",key);status(r,200);var original=body(r);r=settle(q,"SUCCESS",key);status(r,200);assertEquals(original,body(r));status(settle(q,"SUCCESS",UUID.randomUUID()),200);assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM membership_paid_periods WHERE payment_transaction_id=?",Integer.class,id));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM audit_logs WHERE entity_type='PAYMENT' AND entity_id=?",Integer.class,id));assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM renewal_payment_events WHERE payment_id=?",Integer.class,id));error(settle(q,"FAILED",key),409,"ERR_PAYMENT_EVENT_KEY_REUSED");}
