 @Test void roleOwnershipAndActiveAccountAreEnforced()throws Exception{var a=actor();var b=actor();UUID m=membership(a,2);var q=quote(a,m,plan(2,"1"));String path="/memberships/"+m+"/renewals";error(call("POST",path,Map.of("planId",q.get("planId")),b.token(),UUID.randomUUID()),404,"ERR_NOT_FOUND");error(call("GET","/payments/"+q.get("id"),(String)null,b.token(),null),404,"ERR_NOT_FOUND");error(call("GET","/memberships/"+m+"/periods",(String)null,b.token(),null),404,"ERR_NOT_FOUND");error(call("POST","/admin/payment-simulator/transactions/"+q.get("id")+"/results",event(q,"SUCCESS",UUID.randomUUID()),a.token(),null),403,"ERR_FORBIDDEN");error(call("GET","/payments/me",(String)null,admin,null),403,"ERR_FORBIDDEN");error(call("GET","/payments/me",(String)null,null,null),401,"ERR_UNAUTHORIZED");assertEquals(0,json.readTree(call("GET","/payments/me",(String)null,b.token(),null).body()).size());jdbc.update("UPDATE users SET status='DISABLED' WHERE id=?",a.user());error(call("POST",path,Map.of("planId",q.get("planId")),a.token(),UUID.randomUUID()),401,"ERR_UNAUTHORIZED");}
 List<HttpResponse<String>> contend(UUID owner,List<Callable<HttpResponse<String>>> work,Runnable beforeUnlock)throws Exception{
  try(var c=RenewalIntegrationDatabase.history.getConnection();var st=c.prepareStatement("SELECT id FROM members WHERE id=? FOR NO KEY UPDATE");var pool=Executors.newFixedThreadPool(work.size())){
   c.setAutoCommit(false);st.setObject(1,owner);st.executeQuery().close();var ready=new CountDownLatch(work.size());var go=new CountDownLatch(1);var futures=new ArrayList<Future<HttpResponse<String>>>();for(var action:work)futures.add(pool.submit(()->{ready.countDown();go.await();return action.call();}));assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();
   long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);int blocked=0;while(System.nanoTime()<deadline){blocked=jdbc.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query ILIKE '%members%'",Integer.class);if(blocked>=work.size())break;Thread.sleep(25);}assertTrue(blocked>=work.size(),"Requests must actually contend on the held Member lock");beforeUnlock.run();c.commit();var results=new ArrayList<HttpResponse<String>>();for(var future:futures)results.add(future.get(15,TimeUnit.SECONDS));return results;
  }
 }
 @Test void concurrentSameKeyCreatesOnePayment()throws Exception{var a=actor();UUID m=membership(a,1),key=UUID.randomUUID();var p=plan(3,"1");var body=Map.of("planId",p.get("id"));Callable<HttpResponse<String>> action=()->call("POST","/memberships/"+m+"/renewals",body,a.token(),key);var r=contend(a.member(),List.of(action,action),()->{});assertEquals(Set.of(200,201),new HashSet<>(r.stream().map(HttpResponse::statusCode).toList()));assertEquals(body(r.get(0)).get("id"),body(r.get(1)).get("id"));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM renewal_payment_quotes WHERE member_id=?",Integer.class,a.member()));}
 @Test void twoIndependentConcurrentSuccessesAppendTwoNonOverlappingPeriods()throws Exception{var a=actor();UUID m=membership(a,1);var p=plan(3,"2");var q1=quote(a,m,p);var q2=quote(a,m,p);var r=contend(a.member(),List.of(()->settle(q1,"SUCCESS",UUID.randomUUID()),()->settle(q2,"SUCCESS",UUID.randomUUID())),()->{});for(var response:r)status(response,200);assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM membership_paid_periods WHERE membership_id=? AND source='RENEWAL'",Integer.class,m));assertEquals(LocalDate.of(2028,3,6),((java.sql.Date)raw(m).get("expiry_date")).toLocalDate());}
 @Test void concurrentDuplicateSuccessAppliesExactlyOnce()throws Exception{var a=actor();UUID m=membership(a,1),key=UUID.randomUUID();var q=quote(a,m,plan(3,"2"));var r=contend(a.member(),List.of(()->settle(q,"SUCCESS",key),()->settle(q,"SUCCESS",key)),()->{});for(var response:r)status(response,200);UUID id=UUID.fromString((String)q.get("id"));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM membership_paid_periods WHERE payment_transaction_id=?",Integer.class,id));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM renewal_payment_events WHERE payment_id=?",Integer.class,id));}
 @Test void settlementUsesClockAfterWaitingForMemberLock()throws Exception{var a=actor();UUID m=membership(a,1);var q=quote(a,m,plan(2,"1"));var r=contend(a.member(),List.of(()->settle(q,"SUCCESS",UUID.randomUUID())),()->clock.value.set(Instant.parse("2028-03-04T17:00:00Z")));status(r.getFirst(),200);assertEquals("2028-03-05",body(r.getFirst()).get("periodStart"));assertEquals("2028-03-04T17:00:00Z",body(r.getFirst()).get("processedAt"));}
 @Test void faultRollbackLeavesPaymentMembershipPeriodEventAndAuditConsistent()throws Exception{
  var a=actor();UUID m=membership(a,1);var q=quote(a,m,plan(2,"1"));UUID id=UUID.fromString((String)q.get("id"));var before=raw(m);String name="renewal_fault_"+UUID.randomUUID().toString().replace("-","");jdbc.execute("CREATE FUNCTION "+name+"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.payment_id='"+id+"'::uuid THEN RAISE EXCEPTION 'Synthetic rollback fault'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER "+name+" BEFORE INSERT ON renewal_payment_events FOR EACH ROW EXECUTE FUNCTION "+name+"()");
  try{var r=settle(q,"SUCCESS",UUID.randomUUID());status(r,500);assertEquals(before,raw(m));assertEquals("PENDING",jdbc.queryForObject("SELECT status FROM payment_transactions WHERE id=?",String.class,id));for(String table:List.of("membership_paid_periods","renewal_result_keys","renewal_payment_events"))assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM "+table+" WHERE "+(table.equals("membership_paid_periods")?"payment_transaction_id":"payment_id")+"=?",Integer.class,id));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM audit_logs WHERE entity_type='PAYMENT' AND entity_id=?",Integer.class,id));}finally{jdbc.execute("DROP TRIGGER "+name+" ON renewal_payment_events");jdbc.execute("DROP FUNCTION "+name+"()");}
 }
