 @Test void bookingAndD01CoverageMustNotBridgeAnUnpaidGap()throws Exception{
  var a=actor();UUID m=membership(a,1);var row=raw(m);UUID plan=(UUID)row.get("plan_id");LocalDate today=LocalDate.of(2028,2,29);
  jdbc.update("UPDATE memberships SET expiry_date=? WHERE id=?",today.plusDays(3),m);jdbc.update("INSERT INTO membership_paid_periods(member_id,membership_id,plan_id,source,start_date,end_date) VALUES(?,?,?,'LEGACY_AGGREGATE',?,?)",a.member(),m,plan,today.plusDays(2),today.plusDays(3));
  var ms=vn.edu.tdtu.fitcenter.domain.entity.Membership.builder().id(m).status(vn.edu.tdtu.fitcenter.domain.enums.MembershipStatus.ACTIVE).startDate(today).expiryDate(today.plusDays(3)).build();
  Instant gap=today.plusDays(1).atTime(9,0).atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toInstant();var ex=assertThrows(vn.edu.tdtu.fitcenter.exception.BookingConflictException.class,()->coverage.validateMembership(ms,gap,gap.plusSeconds(5400),clock.instant()));assertEquals("ERR_MEMBERSHIP_NOT_COVERED",ex.getCode());
  Instant covered=gap.plusSeconds(86400);assertDoesNotThrow(()->coverage.validateMembership(ms,covered,covered.plusSeconds(5400),clock.instant()));
  var user=vn.edu.tdtu.fitcenter.domain.entity.User.builder().role(vn.edu.tdtu.fitcenter.domain.enums.Role.MEMBER).status(vn.edu.tdtu.fitcenter.domain.enums.AccountStatus.ACTIVE).build();var booking=vn.edu.tdtu.fitcenter.domain.entity.Booking.builder().status(vn.edu.tdtu.fitcenter.domain.enums.BookingStatus.CONFIRMED).startAt(gap.atOffset(ZoneOffset.UTC)).endAt(gap.plusSeconds(5400).atOffset(ZoneOffset.UTC)).build();var eligibility=new vn.edu.tdtu.fitcenter.service.ServiceEligibilityValidator(coverage).check(booking,user,ms,gap);assertFalse(eligibility.eligible());assertTrue(eligibility.reasonCodes().toString().contains("MEMBERSHIP_INACTIVE"));
 }

